        i += 2;
        break;
      }
      i++;
    }
    return _EscSeq(raw: s.substring(start, i), length: i - start);
  } else {
    // Single-char escape (e.g. \x1b7, \x1b8)
    return _EscSeq(raw: s.substring(start, start + 2), length: 2);
  }
}

