// TEMPORARY review-verification scratch test — deleted after the review run.
import 'dart:convert';
import 'dart:io';

import 'package:test/test.dart';

import 'package:dart_tui/src/renderer.dart';
import 'package:dart_tui/src/view.dart';

View newView(String s) => View(content: s);

class _SinkForward implements IOSink {
  _SinkForward(this._target);
  final StringBuffer _target;
  @override
  void write(Object? obj) => _target.write(obj);
  @override
  void writeln([Object? obj = '']) => _target.writeln(obj);
  @override
  void writeAll(Iterable<Object?> objects, [String separator = '']) =>
      _target.writeAll(objects, separator);
  @override
  void writeCharCode(int charCode) => _target.writeCharCode(charCode);
  @override
  Future<void> flush() async {}
  @override
  Future<void> close() async {}
  @override
  Future<void> get done async {}
  @override
  void add(List<int> data) {}
  @override
  void addError(Object error, [StackTrace? stackTrace]) {}
  @override
  Future<void> addStream(Stream<List<int>> stream) async {}
  @override
  Encoding get encoding => utf8;
  @override
  set encoding(Encoding value) {}
}

void main() {
  test('REPRO A: full redraw, blank top+bottom edges => CSI S rows-1?', () {
    // Frame 1: 12 rows, rows 0..10 contentful distinct, row 11 blank.
    final prev = [for (var i = 0; i < 11; i++) 'r$i', ''].join('\n');
    // Frame 2: full redraw - row 0 blank, rows 1..11 contentful distinct.
    final next = ['', for (var i = 1; i <= 11; i++) 'n$i'].join('\n');
    final buf = StringBuffer();
    final renderer = CellRenderer(
      output: _SinkForward(buf),
      logSink: null,
      defaultAltScreen: false,
      defaultHideCursor: false,
    );
    renderer.render(newView(prev));
    buf.clear();
    renderer.render(newView(next));
    final out = buf.toString();
    // ignore: avoid_print
    print('EMITTED: ${jsonEncode(out)}');
    expect(RegExp(r'\x1b\[11S').hasMatch(out), isTrue,
        reason: 'degenerate tail: k=rows-1 won sole eligibility from the '
            'single blank-blank row pair');
    // Convergence: an idle follow-up frame is silent (belief correct).
    buf.clear();
    renderer.render(newView(next));
    expect(buf.toString(), '');
  });

  test('REPRO B: same shape but small true scroll => op still correct', () {
    final prev = [for (var i = 0; i < 11; i++) 'r$i', ''].join('\n');
    // True scroll up by 1 with a fresh tail; top edge becomes blank.
    final next = [for (var i = 1; i <= 11; i++) 'r$i', ''].join('\n');
    final buf = StringBuffer();
    final renderer = CellRenderer(
      output: _SinkForward(buf),
      logSink: null,
      defaultAltScreen: false,
      defaultHideCursor: false,
    );
    renderer.render(newView(prev));
    buf.clear();
    renderer.render(newView(next));
    final out = buf.toString();
    // ignore: avoid_print
    print('EMITTED B: ${jsonEncode(out)}');
    expect(RegExp(r'\x1b\[1S').hasMatch(out), isTrue,
        reason: 'true scroll still takes the fast path');
  });
}

